SELECT REPORT_DATE AS `报告期`, FUND_NAME AS `基金名称`, ROUND(SUM(RATIO_IN_NV) * 100, 2) AS `前十大重仓股合计占净值比例(%)` FROM (SELECT REPORT_DATE, FUND_NAME, RATIO_IN_NV FROM FUND_PORTFOLIO_DETAIL WHERE FUND_NAME LIKE '%大成高新技术产业股票A%' AND REPORT_DATE = '2026-06-30' AND FUND_HOLDING_SOURCE_ID = 1 AND RATIO_IN_NV IS NOT NULL AND HISVALID = 1 ORDER BY MARKET_VALUE DESC LIMIT 10) t GROUP BY REPORT_DATE, FUND_NAME;
